 55	  innertopmargin=6pt,innerbottommargin=6pt,
 56	  skipabove=8pt,skipbelow=8pt
 57	]{draftnotebox}
 58	\newcommand{\note}[1]{%
 59	\begin{draftnotebox}%
 60	{\sffamily\footnotesize\color{draftnotebar}\textsc{Draft note}}\\[2pt]
 61	{\sffamily\small #1}%
 62	\end{draftnotebox}}
 63	%\marginnote{Some text that gets put into the margin} places the text in
 64	%the margin, pretty much vertically centered on the line where the marginnote
 65	%occurs in the input.
 66	\renewcommand{\marginparwidth}{.7in}
 67	% Matching treatment for \marginnote, minus the box: tiny colored sans
 68	% behind the same left bar, sized to \marginparwidth.
 69	\newcommand{\marginnote}[1]{%
 70	\marginpar{\raggedright\noindent\tolerance=1000{%
 71	{\color{draftnotebar}\vrule width 1.5pt}\hspace{3pt}%
 72	\parbox[t]{\dimexpr\marginparwidth-4.5pt\relax}{\sffamily\tiny\color{draftnotebar}#1}}}}
